import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.oyZO4ogf.js";const u=JSON.parse('{"title":"Dev workflow","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev-workflow.md","filePath":"guide/dev-workflow.md","lastUpdated":1794479920000}'),n={name:"guide/dev-workflow.md"};function i(r,e,p,l,d,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="dev-workflow" tabindex="-1">Dev workflow <a class="header-anchor" href="#dev-workflow" aria-label="Permalink to &quot;Dev workflow&quot;">​</a></h1><p>Hot reload for Svelte and Kotlin, debugging and the dev proxy.</p><p>One command runs everything. Then open Ktor&#39;s port, not Vite&#39;s:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><p>It starts Vite, keeps Kotlin compiling and runs your app. Save a Svelte file and the page hot reloads. Save a Kotlin file and the app restarts, and with <code>generateTs</code> on your TypeScript updates a moment later, so type errors show up in the editor right away. A restart loses anything your app keeps in memory. Stopping the task stops all three. In IntelliJ, this is the <code>Dev</code> run configuration.</p><p>All three write to one console in the same shape, so you can tell them apart at a glance:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10:17:17  app      INFO   Application started in 0.959 seconds.</span></span>
<span class="line"><span>10:17:17  vite     INFO   (ssr) connected.</span></span>
<span class="line"><span>10:17:31  kotlin   ERROR  file:///home/me/shop/src/main/kotlin/shop/Routes.kt:24:16 Initializer type mismatch: expected &#39;Int&#39;, actual &#39;String&#39;.</span></span>
<span class="line"><span>10:17:32  kotlin   ERROR  does not compile: 1 error</span></span>
<span class="line"><span>10:17:34  kotlin   INFO   compiled</span></span></code></pre></div><p>Each source has its own color, and warnings and errors stand out. Compiler errors and browser stack traces point to your files as <code>file:///...:line:column</code> links, which IntelliJ opens at that line when you click them. Browser frames such as <code>http://localhost:8080/src/routes/+page.svelte:12:5</code> are turned into links to the file in <code>frontend/</code>. App lines keep the time and level your logging framework printed, and show the logger&#39;s class name when it isn&#39;t <code>Application</code>. Vite&#39;s start banner, its copies of browser console messages, which ktor-svelte forwards itself, and Gradle&#39;s build failure boilerplate are left out, because the ready message above already lists the URLs and the compiler errors say what failed. Colors are off when <code>CI</code> or <code>NO_COLOR</code> is set, or the terminal is <code>dumb</code>.</p><p>When Kotlin stops compiling, the app keeps running its last good version, and the compiler errors appear in the browser in Vite&#39;s error overlay, with the file and line of each. Click the file to open it in your editor, or press Esc to hide the overlay until the errors change. It disappears once the code compiles again.</p><p>An <strong>API</strong> button in the bottom right corner of the page lists the last 100 API calls the app answered: method, path, status, how long the server took, and the <code>X-Request-Id</code> on hover. Calls that failed validation show the message for each field, and the button turns red while any call failed. It only exists while ktor-svelte proxies to Vite, so production pages never contain it. Turn it off with <code>dev { panel = false }</code>.</p><p>Browser console output lands in the same console as your app. Every <code>console.log</code>, <code>info</code>, <code>debug</code>, <code>warn</code> and <code>error</code>, uncaught errors and unhandled promise rejections are sent to the app and logged by the <code>ktor-svelte.browser</code> logger, with the page they came from:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10:21:19 WARN  ktor-svelte.browser Probe warning {&quot;id&quot;:7} [/notes]</span></span>
<span class="line"><span>10:21:19 ERROR ktor-svelte.browser Error: Probe crash</span></span></code></pre></div><p>Objects are written as JSON, and errors with their stack trace. <code>console.debug</code> uses the DEBUG level, so it only shows when you enable it in your logging configuration. Like the panel, this only exists while ktor-svelte proxies to Vite, and only for requests from this machine. Turn it off with <code>dev { browserLogs = false }</code>.</p><p>Once the app is listening, it prints the links you need, so they do not get lost in the output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ktor-svelte is ready. Open the app URL, not the Vite one:</span></span>
<span class="line"><span>  App:      http://localhost:8080</span></span>
<span class="line"><span>  API docs: http://localhost:8080/api/docs</span></span>
<span class="line"><span>  Vite:     http://localhost:5173</span></span></code></pre></div><p>It also opens the app in your default browser, the first time only, so restarts do not open new tabs. It never does so in CI or on a Linux machine without a display. Turn it off with <code>svelte { dev { openBrowser = false } }</code>. The API docs line appears when <code>apiDocs = true</code>. After a restart it prints one line with the app URL instead. The URL comes from Ktor&#39;s <code>Responding at</code> log line, so keep Ktor&#39;s INFO logging on for the application logger.</p><p>For the edits you make most, install the live templates once with <code>./gradlew svelteLiveTemplates --install</code> and restart the IDE. In Kotlin, <code>ksget</code>, <code>kspost</code> and <code>kspage</code> write routes, and <code>ksdto</code> and <code>ksinput</code> write DTOs with bounds and rules. In TypeScript, <code>ksapi</code> calls the generated client, <code>ksload</code> writes a <code>load</code> function with <code>apiWith</code>, and <code>kserror</code> wraps code in typed error handling.</p><p>To debug your Kotlin code, start <code>Dev</code> as usual and then start the <code>Debug app</code> run configuration in debug mode. IntelliJ debugs Gradle tasks only when they run a JVM through Gradle, and <code>svelteDevAll</code> starts the app itself, so the app instead listens for a debugger on <code>127.0.0.1:5005</code> (see <code>dev.debugPort</code>). <code>Debug app</code> has auto restart on, so it reconnects after each restart. Outside IntelliJ, attach any JDWP debugger to that port. Two apps running <code>svelteDevAll</code> at once need different debug ports.</p><p>To do both in one click, run <code>Dev and debug</code>. It starts <code>Dev</code> and attaches the Kotlin debugger, and stopping it stops both.</p><p>To debug the frontend, run <code>Debug frontend</code> in debug mode while <code>Dev</code> runs. IntelliJ opens the app at <code>http://localhost:8080</code> in Chrome with its JavaScript debugger attached, and breakpoints in <code>.svelte</code> and <code>.ts</code> files under <code>frontend/</code> work through Vite&#39;s source maps. If your app runs on another port, change the URL in that run configuration.</p><p>At startup in development, the app logs which protections and settings are active, so a 403, 413 or 429 does not come as a surprise:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ktor-svelte settings:</span></span>
<span class="line"><span>  API prefixes: /api</span></span>
<span class="line"><span>  Dev proxy: http://localhost:5173</span></span>
<span class="line"><span>  Origin check: on (same host only)</span></span>
<span class="line"><span>  Body limit: 1 MiB, JSON depth: 64</span></span>
<span class="line"><span>  Rate limit: 120 writes per 1m per client, FixedWindow</span></span>
<span class="line"><span>  Content-Security-Policy: off while proxying to Vite</span></span>
<span class="line"><span>  Error details: hidden in production, shown now</span></span>
<span class="line"><span>  API compression: on, request IDs: on</span></span></code></pre></div><p>Production logs only the version and the build fingerprint.</p><p>In development, API calls that take 500 ms or longer are logged with the route that served them, so you can jump straight to the code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ktor-svelte: slow API call GET /api/notes?search=milk took 812 ms (notes/Routes.kt:19)</span></span></code></pre></div><p>Change the threshold with <code>dev { slowApiCall = 200.milliseconds }</code>, or set it to <code>null</code> to turn it off. Production never logs these.</p><p>Open <code>http://localhost:8080/_ktor-svelte/routes</code> to see every Ktor route next to every SvelteKit page, with the file and line of each route and a warning on routes that hide a page. Ask for <code>application/json</code> to get the same table as JSON. It exists only in development and answers only requests from this machine.</p><p>Prefer separate terminals? Run these instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDev</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Psvelte.dev=true</span></span></code></pre></div><p>In development mode the runtime proxies to Vite if it is reachable, otherwise serves built files if they exist, and otherwise returns a 503 explaining how to start Vite. API prefixes are never proxied.</p><p>The proxy only answers requests from this machine, so your frontend source is not open to everyone on your network, even though Ktor listens on all interfaces. Requests from elsewhere get your built files, or a 403 if there are none. It never forwards cookies or <code>Authorization</code> headers. It also refuses to start if <code>dev.url</code> points at another machine. To test from your phone or use Vite in another container, set <code>dev { allowRemote = true }</code>, and only on a network you trust.</p><p>The proxy forwards HTTP only. POST, PUT, PATCH and DELETE requests are forwarded too, with their body, so Vite endpoints and SvelteKit form actions work in dev. Paths under your API prefixes are never proxied, whatever the method. <code>server.hmr.clientPort</code> in the quick start makes Vite&#39;s client connect straight to Vite. Without it HMR still works, but the browser logs one WebSocket error before Vite falls back. Either way, the browser must be able to reach Vite&#39;s port, so a remote machine or container needs that port exposed.</p><p>With two terminals, if a Gradle process is killed rather than stopped normally, Vite or the app can keep running and hold its port. Run <code>./gradlew --stop</code>, or stop the process listening on that port. <code>svelteDevAll</code> stops its children even when its terminal is closed.</p>`,34)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
